use std::collections::BTreeMap;

use serde::{Deserialize, Serialize};

use crate::delta::ObservedClass;
use crate::ids::{ChangeId, ChangeSetId, EntityId, RelPath, SnapshotId, Timestamp};

#[derive(Clone, PartialEq, Eq, Serialize, Deserialize, Debug)]
pub enum Intent {
    Refactor,
    Fix,
    Feature,
    Docs,
    Other(String),
}

/// Who a [`Op::Note`] is hung on. Review, mail, and claims share this one op
/// (DEBATE §19): a message about a changeset *is* a review note.
#[derive(Clone, PartialEq, Eq, Serialize, Deserialize, Debug)]
pub enum NoteTo {
    Checkout(String),
    All,
    Changeset(ChangeSetId),
    Entity(EntityId),
}

/// What kind of coordination a [`Op::Note`] is.
#[derive(Clone, Copy, PartialEq, Eq, Serialize, Deserialize, Debug)]
pub enum NoteKind {
    Note,
    Approve,
    RequestChanges,
    Claim,
    Release,
}

#[derive(Clone, PartialEq, Eq, Serialize, Deserialize, Debug)]
pub enum Op {
    Rename {
        id: EntityId,
        new: String,
    },
    Move {
        id: EntityId,
        parent: Option<EntityId>,
        ordinal: Option<u32>,
    },
    Relocate {
        id: EntityId,
        file: RelPath,
        ordinal: u32,
    },
    Extract {
        id: EntityId,
        new_parent: Option<EntityId>,
        ordinal: u32,
    },
    Inline {
        id: EntityId,
    },
    AddDef {
        id: EntityId,
        parent: Option<EntityId>,
        ordinal: u32,
        definition: String,
        intent: Intent,
        /// Recorded target. Absent on ops from before this field existed
        /// (JSON) and on tests that still omit it; apply then uses the parent
        /// file, else the first tracked source file.
        #[serde(default)]
        file: Option<RelPath>,
    },
    Delete {
        id: EntityId,
        intent: Intent,
    },
    EditDef {
        id: EntityId,
        definition: String,
        intent: Intent,
    },
    Merge {
        other: ChangeId,
    },
    Undo,
    New {
        change: ChangeId,
    },
    Describe {
        msg: String,
    },
    /// Start a sibling change: parent is the current change's parent, then name it.
    Branch {
        name: String,
    },
    /// Working-copy reconciliation. Snapshot is `after.root` on the log entry so O5 can replay.
    Absorb,
    /// Resolution of conflict `conflict` (an index into the merge snapshot's list) by
    /// taking one side. Recorded as itself so replay reproduces the resolved snapshot.
    Resolve {
        conflict: u32,
        take: Take,
    },
    /// `svc op restore <n>`: return to the view as it stood right after op `n`.
    /// Distinct from `Undo` so the log names the verb.
    Restore {
        at: u64,
    },
    /// Review, mail, and claims. Last on purpose: postcard writes a variant as its
    /// index, so a variant added anywhere but the end re-labels every op already in
    /// every store. `op_wire_format` pins the order.
    Note {
        to: NoteTo,
        kind: NoteKind,
        text: String,
    },
}

/// Which side a conflict resolution keeps: the merge's first parent, its second, or the base —
/// or, for a binding conflict, the code as it now stands (`Accept`: the author fixed or
/// approved the binding and says so).
#[derive(Clone, Copy, PartialEq, Eq, Serialize, Deserialize, Debug)]
pub enum Take {
    A,
    B,
    Base,
    Accept,
}

impl Op {
    pub fn intent(&self) -> Option<&Intent> {
        match self {
            Op::AddDef { intent, .. } | Op::EditDef { intent, .. } | Op::Delete { intent, .. } => {
                Some(intent)
            }
            _ => None,
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::ids::EntityId;

    #[test]
    fn add_def_json_without_file_defaults_to_none() {
        let id = EntityId::new();
        let v = serde_json::json!({
            "AddDef": {
                "id": id,
                "parent": null,
                "ordinal": 0,
                "definition": "fn x() {}",
                "intent": "Feature"
            }
        });
        let op: Op = serde_json::from_value(v).unwrap();
        match op {
            Op::AddDef {
                file, definition, ..
            } => {
                assert!(file.is_none());
                assert_eq!(definition, "fn x() {}");
            }
            other => panic!("{other:?}"),
        }
    }

    #[test]
    fn restore_json_round_trips_the_op_index() {
        let op = Op::Restore { at: 3 };
        let v = serde_json::to_value(&op).unwrap();
        assert_eq!(v, serde_json::json!({"Restore":{"at":3}}));
        let back: Op = serde_json::from_value(v).unwrap();
        assert!(matches!(back, Op::Restore { at: 3 }));
    }

    #[test]
    fn note_json_round_trips_the_three_fields() {
        let op = Op::Note {
            to: NoteTo::All,
            kind: NoteKind::Approve,
            text: "ship it".into(),
        };
        let v = serde_json::to_value(&op).unwrap();
        assert_eq!(
            v,
            serde_json::json!({"Note":{"to":"All","kind":"Approve","text":"ship it"}})
        );
        let back: Op = serde_json::from_value(v).unwrap();
        assert!(matches!(
            back,
            Op::Note {
                to: NoteTo::All,
                kind: NoteKind::Approve,
                text
            } if text == "ship it"
        ));
    }
}

#[derive(Clone, PartialEq, Eq, Serialize, Deserialize, Debug)]
pub struct View {
    pub root: SnapshotId,
    pub heads: BTreeMap<ChangeId, SnapshotId>,
}

#[derive(Clone, PartialEq, Eq, Serialize, Deserialize, Debug)]
pub struct OpLogEntry {
    pub op: Op,
    pub observed: Option<ObservedClass>,
    pub at: Timestamp,
    pub group: Option<ChangeSetId>,
    pub before: View,
    pub after: View,
}

impl OpLogEntry {
    pub fn declared(&self) -> Option<&Intent> {
        self.op.intent()
    }

    pub fn flagged(&self) -> bool {
        match (self.declared(), self.observed) {
            (Some(Intent::Refactor), Some(ObservedClass::BindingChanging)) => true,
            (Some(Intent::Docs), Some(o))
                if !matches!(o, ObservedClass::DocsOnly | ObservedClass::Alpha) =>
            {
                true
            }
            (Some(Intent::Fix), Some(ObservedClass::Alpha | ObservedClass::DocsOnly)) => true,
            (None, Some(ObservedClass::BindingChanging)) => true,
            _ => false,
        }
    }
}

EditDef.definition:
/// `svc resolve <n> --take a|b|base`: choose one side of an attribute, content, delete/edit or
/// add/add conflict. Binding conflicts have no side to take and are rejected here.
/// The snapshot `cur` becomes when conflict `n` is resolved by taking `take`. Pure over the
/// store, so `resolve` and replay produce the same snapshot from the same op.
pub fn resolved_snapshot(store: &dyn Store, cur: &Snapshot, n: usize, take: Take) -> Result<(Snapshot, SnapshotId)> {
    let conflict = cur
        .conflicts
        .get(n)
        .cloned()
        .ok_or_else(|| Error::NotFound(format!("conflict {n}")))?;
    let [a_id, b_id] = cur.parents.as_slice() else {
        return Err(Error::Other("current snapshot is not a merge".into()));
    };
    let (a_id, b_id) = (*a_id, *b_id);
    let side_a = store.get_snapshot(a_id)?;
    let side_b = store.get_snapshot(b_id)?;
    let base_id = lca(store, a_id, b_id)?
        .ok_or_else(|| Error::Other("no common ancestor".into()))?;
    let base = store.get_snapshot(base_id)?;
    let pick = |id: EntityId| -> Option<EntityRecord> {
        match take {
            Take::A => side_a.entities.get(&id).cloned(),
            Take::B => side_b.entities.get(&id).cloned(),
            Take::Base => base.entities.get(&id).cloned(),
            Take::Accept => cur.entities.get(&id).cloned(),
        }
    };

    let mut next = cur.clone();
    match &conflict {
        // The code as it stands is the resolution: the author fixed the binding with an
        // edit-def, or means it; nothing to pick from a side.
        Conflict::Binding { .. } if take == Take::Accept => {}
        Conflict::Binding { .. } => {
            return Err(Error::Other(
                "a binding conflict has no side to take; fix the code with edit-def, then `svc resolve <n> --take accept`".into(),
            ));
        }
        Conflict::Attr { id, sides } => {
            let value = match take {
                Take::A => sides.adds().next().cloned(),
                Take::B => sides.adds().nth(1).cloned(),
                Take::Base => sides.removes().next().cloned(),
                Take::Accept => None,
            }
            .ok_or_else(|| Error::Other("that side has no value".into()))?;
            let rec = next.entities.get_mut(id).ok_or(Error::NoSuchEntity(*id))?;
            match value {
                AttrValue::Name(n) => rec.name = n,
                AttrValue::Parent(p) => rec.parent = p,
                AttrValue::File(f) => rec.file = f,
                AttrValue::Ordinal(o) => rec.ordinal = o,
            }
        }
        Conflict::Content { id, .. } => {
            let chosen = pick(*id).ok_or(Error::NoSuchEntity(*id))?;
            let rec = next.entities.get_mut(id).ok_or(Error::NoSuchEntity(*id))?;
            rec.content = chosen.content;
            rec.bytes = chosen.bytes;
        }
        Conflict::DeleteEdit { id, .. } => match pick(*id) {
            Some(rec) => {
                next.entities.insert(*id, rec);
            }
            None => {
                next.entities.remove(id);
            }
        },
        Conflict::AddAdd { a, b, .. } => {
            let drop = match take {
                Take::A => *b,
                Take::B => *a,
                Take::Base | Take::Accept => {
                    return Err(Error::Other("add/add has no base side; take a or b".into()));
                }
            };
            next.entities.remove(&drop);
        }
    }
    next.conflicts.remove(n);
    Ok((next, base_id))
}

